import{_ as t,o as i,c as a,ae as n}from"./chunks/framework.Czhw_PXq.js";const g=JSON.parse('{"title":"💎 Code Quality & Technical Debt Policy - TenderCheck AI","description":"","frontmatter":{},"headers":[],"relativePath":"standards/code_quality_policy.md","filePath":"standards/code_quality_policy.md"}'),o={name:"standards/code_quality_policy.md"};function r(s,e,c,l,d,h){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="💎-code-quality-technical-debt-policy-tendercheck-ai" tabindex="-1">💎 Code Quality &amp; Technical Debt Policy - TenderCheck AI <a class="header-anchor" href="#💎-code-quality-technical-debt-policy-tendercheck-ai" aria-label="Permalink to &quot;💎 Code Quality &amp; Technical Debt Policy - TenderCheck AI&quot;">​</a></h1><h2 id="_1-detection-of-code-smells" tabindex="-1">1. Detection of Code Smells <a class="header-anchor" href="#_1-detection-of-code-smells" aria-label="Permalink to &quot;1. Detection of Code Smells&quot;">​</a></h2><p>[cite_start]The system must be audited regularly to identify and resolve patterns that indicate poor design or maintainability issues[cite: 652, 653]:</p><ul><li>[cite_start]<strong>Magic Numbers &amp; God Objects</strong>: Avoid hardcoded values without context and classes that take on too many responsibilities.</li><li>[cite_start]<strong>Code Duplication</strong>: Adhere strictly to the <strong>DRY (Don&#39;t Repeat Yourself)</strong> principle to ensure logic is centralized.</li><li>[cite_start]<strong>Automated Tooling</strong>: Use <strong>ESLint</strong> and <strong>Sonar</strong> to automatically detect smells and enforce style guides.</li></ul><h2 id="_2-technical-debt-management" tabindex="-1">2. Technical Debt Management <a class="header-anchor" href="#_2-technical-debt-management" aria-label="Permalink to &quot;2. Technical Debt Management&quot;">​</a></h2><p>[cite_start]Technical debt must be handled pragmatically to ensure project sustainability:</p><ul><li>[cite_start]<strong>Architecture Decision Records (ADRs)</strong>: Document key decisions and the reasoning behind them to prevent &quot;hidden&quot; debt.</li><li>[cite_start]<strong>Refactoring Strategy</strong>: Apply secure refactoring techniques to keep the <strong>Domain Layer</strong> isolated from infrastructure changes[cite: 654, 1093].</li><li>[cite_start]<strong>Pragmatic Documentation</strong>: Use ADRs to record when a temporary solution is chosen over a permanent one, including the justification and potential risks.</li></ul><h2 id="_3-engineering-principles" tabindex="-1">3. Engineering Principles <a class="header-anchor" href="#_3-engineering-principles" aria-label="Permalink to &quot;3. Engineering Principles&quot;">​</a></h2><ul><li>[cite_start]<strong>SOLID Principles</strong>: Every code change must strive to follow SOLID principles to enhance modularity and testability.</li><li>[cite_start]<strong>Clean Architecture</strong>: Ensure the core business logic is independent of frameworks, UI, and external agencies.</li><li><strong>Traceability</strong>: Maintain a clear history of changes and decisions within the repository using the &quot;Docs as Code&quot; philosophy.</li></ul>',9)])])}const p=t(o,[["render",r]]);export{g as __pageData,p as default};
